+                            .minimumShouldMatch(1)
+                            .should(QueryBuilders.boolQuery().mustNot(parseKqlQuery(queryA)))
+                            .should(parseKqlQuery(queryB))
+                    )
+                );
+                assertThat(parsedQuery, equalTo(parseKqlQuery(Strings.format("(NOT %s) OR %s", queryA, queryB))));
+            }
+        }
+    }
